dark.customCSS:
:root {
	--obs-glass: color-mix(in oklab, var(--color-gray-900) 76%, transparent);
	--obs-sidebar: color-mix(in oklab, var(--color-gray-950) 82%, transparent);
	--obs-bubble: color-mix(in oklab, var(--color-gray-800) 70%, transparent);
	--obs-selected: color-mix(in oklab, var(--color-gray-600) 30%, transparent);
	--obs-line: color-mix(in oklab, var(--color-gray-400) 16%, transparent);
	--obs-sheen: color-mix(in oklab, white 7%, transparent);
	--obs-shade: color-mix(in oklab, black 75%, transparent);
	--obs-focus: color-mix(in oklab, var(--color-gray-300) 45%, transparent);
	--obs-ring: color-mix(in oklab, var(--color-gray-300) 10%, transparent);
	--obs-heading: var(--color-gray-50);
	--obs-mark: color-mix(in oklab, var(--color-gray-400) 35%, transparent);
}

/* Volcanic glass: no color at all, one lit edge along the top of the
   input and your bubble. Shapes are Open WebUI's own. */
#message-input-container {
	background-color: var(--obs-glass) !important;
	border-color: var(--obs-line) !important;
	backdrop-filter: blur(16px);
	box-shadow: inset 0 1px 0 var(--obs-sheen), 0 12px 36px -18px var(--obs-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--obs-focus) !important;
	box-shadow: inset 0 1px 0 var(--obs-sheen), 0 0 0 3px var(--obs-ring), 0 12px 36px -18px var(--obs-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--obs-bubble) !important;
	box-shadow: inset 0 0 0 1px var(--obs-line), inset 0 1px 0 var(--obs-sheen);
}
#sidebar {
	background-color: var(--obs-sidebar) !important;
	border-inline-end: 1px solid var(--obs-line);
}
#sidebar-chat-item.selected { background-color: var(--obs-selected); }
.markdown-prose :is(h1, h2, h3) { color: var(--obs-heading); letter-spacing: -0.01em; }
.markdown-prose a { color: inherit; text-decoration-color: var(--obs-focus); text-underline-offset: 3px; }
.markdown-prose :is(hr, blockquote) { border-color: var(--obs-line); }
html { scrollbar-color: var(--obs-line) transparent; }
::selection { background-color: var(--obs-mark); }

